bool isValid(string s) {
    stack<char> st;
    unordered_map<char,char> m{{')','('},{']','['},{'}','{'}};
    for (char c : s) {
        if (m.count(c)) {
            if (st.empty() || st.top() != m[c]) return false;
            st.pop();
        } else st.push(c);
    }
    return st.empty();
}

vector<int> nextGreater(vector<int>& a) {
    int n = a.size();
    vector<int> res(n, -1);
    stack<int> st;   // holds indices, decreasing values
    for (int i = 0; i < n; i++) {
        while (!st.empty() && a[st.top()] < a[i]) {
            res[st.top()] = a[i];
            st.pop();
        }
        st.push(i);
    }
    return res;
}
